        tracked_ctxs.append([])
      ret = func(*args, **kwargs)
      if TRACK_MATCH_STATS >= 2 and name_fxn is not None: tracked_keys[-1] = f"{name_fxn(ret)} n{_name_cnt[func.__name__]}"
      return ret
    return __wrapper
  return _decorator

