  def', '__slots__ = ("op", "dtype", "arg", "name", "src")', 'self.early_reject = {pp.op[0] for pp in upat_match if pp.op is not None and len(pp.op) == 1}', 'with open(fn) as f:', 'with open(fn:=temp("rewrites.pkl", append_user=True), "wb") as f:', 'formatted_parents = [(uops.index(x) if x.op is not Ops.CONST else f"{x.arg}") if x in uops else "--" for x in u.src]', 'newuops = [uop.substitute({X:newX}).simplify().substitute({newX:X}).simplify() for X,newX in candidate]', 'while mop is not self.base:
